from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(17,'espace','Solides, disques et volumes','3 · Espace et géométrie',
'Perspectives · Patrons · Prismes · Cylindres · Capacités',
['Relier perspectives, vues et patrons.','Calculer les volumes usuels et l’aire du disque.','Convertir volumes et capacités.'],['Aires, carrés et cubes.'],[
page(1,'Représenter l’espace',
bloc('definition',r'Un pavé droit a six faces rectangulaires ; un cube a six faces carrées. Un prisme droit a deux bases polygonales identiques et parallèles, et des faces latérales rectangulaires. Un cylindre de révolution a deux bases en forme de disques et une surface latérale courbe.'),
r'@FIG:cours-solides@',
bloc('savoirfaire',r'En perspective cavalière, les arêtes parallèles restent parallèles sur le dessin. Les arêtes cachées sont en pointillés. Les longueurs obliques représentées ne sont pas à mesurer directement. Des vues de dessus et de face aident à dénombrer les cubes d’un empilement.','Lire une représentation'),
bloc('attention',r'Un dessin en perspective peut masquer des cubes. Un tableau de hauteurs, une vue ou une précision du texte doit permettre de décider ce qui est caché.')),
page(2,'Déplier un solide',
bloc('definition',r'Un patron est une figure plane qui, par pliage ou assemblage, donne la surface du solide sans chevauchement des faces. Deux faces qui se rejoignent ont des bords de même longueur.'),
r'@FIG:cours-patrons@',
bloc('propriete',r'Un prisme droit de base triangulaire a deux triangles identiques et trois rectangles. Le patron d’un cylindre comporte deux disques de rayon $r$ et un rectangle de hauteur $h$ et de longueur $2\pi r$, le périmètre d’un disque.'),
bloc('savoirfaire',r'Associer d’abord chaque face du patron à la perspective. Contrôler les longueurs des bords, puis imaginer le pliage. Pour un cube, six carrés seuls ne suffisent pas : certains assemblages se recouvrent au pliage.','Vérifier avant de découper')),
page(3,'Volumes et unités',
bloc('propriete',r'$V_{\mathrm{cube}}=c^3$, $V_{\mathrm{pavé}}=L\ell h$, $V_{\mathrm{prisme}}=B h$, où $B$ est l’aire d’une base et $h$ la distance entre les deux bases. Les trois dimensions doivent être dans la même unité.'),
tableau(['Unité','m$^3$','dm$^3$','cm$^3$'],[['Vers la suivante',r'$\times1000$',r'$\times1000$','']]),
bloc('propriete',r'$1$ L $=1$ dm$^3$ ; $1$ mL $=1$ cm$^3$ ; $1$ m$^3=1000$ L. Les unités de capacité suivent les préfixes décimaux : $1$ L $=100$ cL $=1000$ mL.'),
bloc('exemple',r'Un prisme de base triangulaire de base 6 cm et hauteur 4 cm a une aire de base de 12 cm$^2$. Pour une longueur de prisme de 10 cm, le volume vaut $12\times10=120$ cm$^3$.'),
bloc('attention',r'Ne pas confondre la hauteur du triangle de base avec la hauteur du prisme. Une aire est en unités carrées, un volume en unités cubes.')),
page(4,'Disque et cylindre',
bloc('propriete',r'Un disque de rayon $r$ a pour aire $\pi r^2$. Le cylindre de rayon $r$ et de hauteur $h$ a pour volume $\pi r^2h$. Le rayon est la moitié du diamètre.'),
r'@FIG:cours-cylindre@',
bloc('exemple',r'Pour $r=3$ cm et $h=8$ cm, l’aire de base est $9\pi$ cm$^2$ et le volume $72\pi$ cm$^3$, soit environ 226 cm$^3$ à l’unité.'),
bloc('savoirfaire',r'On découpe le disque en secteurs très fins, que l’on dispose tête-bêche : on obtient presque un parallélogramme de base $\pi r$, la moitié du périmètre, et de hauteur $r$. Son aire vaut $\pi r\times r=\pi r^2$. Comme pour le prisme, le volume du cylindre est l’aire de base multipliée par la hauteur.','Comprendre la formule'),
bloc('savoirfaire',r'Conserver $\pi$ dans le résultat exact. Utiliser ensuite la calculatrice pour l’arrondi demandé. Ne pas remplacer trop tôt $\pi$ par 3,14, ce qui peut dégrader l’arrondi final.','Exact puis approché'),
bloc('attention',r'Pour peindre un objet, on calcule une aire de surface ; pour le remplir, un volume ou une capacité. Les données et la question indiquent la formule utile.'))
],[
E('Reconnaître un solide',r'Identifier les solides A et B et donner le nombre de faces planes de chacun.',r'A est un $\res{pavé\ droit}$ avec six faces rectangulaires. B est un $\res{prisme\ droit\ triangulaire}$ avec deux triangles et trois rectangles, soit cinq faces.','Observer les bases et les faces latérales.','assert 6==6 and 2+3==5',figure='sol-1'),
E('Volume d’un cube',r'Un cube a un côté de 4 cm. Calculer son volume.',r'$V=4^3=\res{64\ \mathrm{cm}^3}$. On compte quatre cubes unité dans chaque direction.','Multiplier les trois dimensions.','assert 4**3==64',figure='sol-2'),
E('Volume d’un pavé',r'Un pavé mesure 7 cm sur 5 cm sur 3 cm. Calculer son volume.',r'$V=7\times5\times3=\res{105\ \mathrm{cm}^3}$. Les trois dimensions sont dans la même unité.','Utiliser longueur fois largeur fois hauteur.','assert 7*5*3==105',figure='sol-3'),
E('Aire d’un disque',r'Un disque a pour rayon 4 cm. Calculer son aire exacte.',r'$A=\pi\times4^2=\res{16\pi\ \mathrm{cm}^2}$. La formule utilise le rayon.','Élever le rayon au carré.','assert pi*4**2==16*pi',figure='sol-4'),
E('Volume et capacité',r'Convertir 2,5 dm$^3$ en litres et en cm$^3$.',r'2,5 dm$^3=\res{2{,}5\ \mathrm L}$ et $\res{2500\ \mathrm{cm}^3}$. Un dm$^3$ vaut 1000 cm$^3$.','Relier les unités de volume et de capacité.','assert Rational("2.5")*1000==2500',figure='sol-5'),
E('Prisme triangulaire',r'La base triangulaire d’un prisme a une base de 6 cm et une hauteur de 4 cm. La longueur du prisme vaut 9 cm. Calculer son volume.',r'L’aire de la base est $6\times4:2=12$ cm$^2$. Le volume vaut $12\times9=\res{108\ \mathrm{cm}^3}$.','Calculer l’aire de base avant le volume.','assert Rational(6*4,2)*9==108',figure='sol-6'),
E('Cylindre',r'Un cylindre a un rayon de 2 cm et une hauteur de 10 cm. Calculer son volume exact, puis arrondir au cm$^3$.',r'$V=\pi\times2^2\times10=\res{40\pi\ \mathrm{cm}^3}$, soit environ $\res{126\ \mathrm{cm}^3}$.','Multiplier l’aire du disque par la hauteur.','assert pi*2**2*10==40*pi and round(float(40*pi))==126',figure='sol-7'),
E('Diamètre donné',r'Un cylindre a un diamètre de 6 cm et une hauteur de 5 cm. Calculer son volume exact.',r'Le rayon vaut $6:2=3$ cm. Donc $V=\pi\times3^2\times5=\res{45\pi\ \mathrm{cm}^3}$. Utiliser 6 comme rayon multiplierait l’aire par quatre.','Passer du diamètre au rayon.','assert pi*Rational(6,2)**2*5==45*pi',figure='sol-8'),
E('Un patron de prisme',r'Un prisme droit a pour base un triangle de côtés 3, 4 et 5 cm et une longueur de 6 cm. Compléter son patron avec les dimensions des trois rectangles.',r'Chaque rectangle relie un côté du premier triangle au côté correspondant du second. Leurs dimensions sont $\res{3\times6}$, $\res{4\times6}$ et $\res{5\times6}$ cm. Les deux triangles sont identiques.','Faire correspondre les bords des faces.','assert 3+4+5==12 and sum(a*6 for a in [3,4,5])==72',figure='sol-9'),
E('Un patron de cylindre',r'Un cylindre a un rayon de 3 cm et une hauteur de 7 cm. Donner les dimensions du rectangle de son patron.',r'Une dimension est la hauteur : $\res{7\ \mathrm{cm}}$. L’autre est le périmètre de base : $2\pi\times3=\res{6\pi\ \mathrm{cm}}$, environ 18,85 cm. Ajouter deux disques de rayon 3 cm.','Dérouler un tour complet de la base.','assert 2*pi*3==6*pi and abs(float(6*pi)-18.85)<.005',figure='sol-10'),
E('Compter des cubes',r'Le tableau de hauteurs vu de dessus indique trois colonnes au premier rang de hauteurs 2, 1, 3 ; au second rang, 1, 2, 0. Combien de cubes y a-t-il ?',r'Chaque nombre donne le nombre de cubes empilés à cette place. Le total vaut $2+1+3+1+2+0=\res9$ cubes, y compris ceux masqués sous les cubes du dessus.','Additionner les hauteurs des piles.','assert sum([2,1,3,1,2,0])==9',figure='sol-11'),
E('Remplir un aquarium',r'Un aquarium intérieur mesure 60 cm sur 30 cm. On le remplit jusqu’à une hauteur de 25 cm. Quel volume d’eau faut-il en litres ?',r'$V=60\times30\times25=45000$ cm$^3$. Comme 1000 cm$^3=1$ L, cela représente $\res{45\ \mathrm L}$. On utilise la hauteur d’eau, pas la hauteur totale du récipient.','Convertir le volume obtenu en capacité.','assert 60*30*25//1000==45',figure='sol-12'),
E('Comparer des récipients',r'A est un pavé de 10 cm sur 8 cm sur 6 cm. B est un cylindre de rayon 4 cm et de hauteur 10 cm. Lequel contient le plus ?',r'$V_A=480$ cm$^3$. $V_B=160\pi\approx502{,}65$ cm$^3$. Le cylindre $\res B$ contient environ $\res{22{,}65\ \mathrm{cm}^3}$ de plus. On compare des volumes dans la même unité.','Calculer chaque capacité avec sa formule.','assert 160*pi>480 and abs(float(160*pi-480)-22.65)<.005',figure='sol-13'),
E('Compléter une perspective',r'On a commencé la représentation en perspective cavalière d’un prisme droit ABCDEF dont la base ABC est un triangle rectangle en A : la face avant est en vraie grandeur et l’arête [BE] est tracée. Reproduire puis compléter le dessin, avec les arêtes cachées en pointillés. Citer ensuite les arêtes de même longueur que [BE] et la face parallèle à ABC.',r'Depuis A et C, on trace des arêtes parallèles à [BE] et de même longueur sur le dessin : on obtient D et F, puis la face arrière DEF, identique à ABC. Les arêtes issues de D, sommet caché, sont en pointillés. Les arêtes $\res{\text{[AD] et [CF]}}$ ont la même longueur que [BE] : c’est la longueur du prisme. La face $\res{DEF}$ est parallèle à ABC ; les faces latérales sont des rectangles.','Garder les arêtes fuyantes parallèles et de même longueur.','A,B,C,D,E,F=(0,0),(3,0),(0,Rational(12,5)),(2,Rational(6,5)),(5,Rational(6,5)),(2,Rational(18,5))\nv=lambda P,Q:(Q[0]-P[0],Q[1]-P[1])\nassert v(A,D)==v(B,E)==v(C,F) and v(A,B)==v(D,E) and v(A,C)==v(D,F)',figure='sol-14'),
E('Une boîte ouverte',r'Une boîte sans couvercle mesure 12 cm sur 8 cm sur 5 cm. Calculer sa capacité en mL et l’aire de carton utilisée, sans languettes.',r'La capacité vaut $12\times8\times5=\res{480\ \mathrm{mL}}$. Le carton comprend le fond et quatre côtés : $12\times8+2\times12\times5+2\times8\times5=\res{296\ \mathrm{cm}^2}$. On n’ajoute pas de couvercle.','Séparer le volume intérieur et l’aire du patron.','assert 12*8*5==480 and 12*8+2*12*5+2*8*5==296',figure='sol-15')
],reperes=['Perspectives, vues et dénombrement','Patrons de pavé, prisme et cylindre','Volumes et conversions de capacité','Aire du disque et volume du cylindre'],deco='geometrie')

chapitre(18,'statistiques','Organiser et interpréter des données','4 · Données, hasard et programmation',
'Effectifs · Fréquences · Diagrammes · Moyenne simple',
['Recueillir et organiser des données.','Calculer des fréquences et choisir une représentation.','Calculer et interpréter une moyenne simple.'],['Fractions, pourcentages et graphiques.'],[
page(1,'Du relevé à la représentation',
bloc('definition',r'Une série statistique rassemble des données. L’effectif d’une valeur ou d’une catégorie est son nombre d’apparitions. L’effectif total est la somme des effectifs. La fréquence d’une catégorie est son effectif divisé par le total non nul.'),
tableau(['Transport','À pied','Vélo','Bus'],[['Effectif','10','6','4'],['Fréquence','50 %','30 %','20 %']]),
r'@FIG:cours-statistiques@',
bloc('savoirfaire',r'Un diagramme en barres compare les catégories ; un diagramme circulaire montre le partage du total ; un graphique cartésien montre une évolution. Choisir la représentation selon la question, avec titres, unités et graduations.','Choisir pour montrer')),
page(2,'Moyenne et lecture critique',
bloc('definition',r'La moyenne simple d’une série numérique est la somme des valeurs divisée par leur nombre. Elle décrit une valeur de partage égal ; elle n’est pas nécessairement une valeur observée.'),
bloc('exemple',r'Pour $4,6,6,8$, la somme est 24 et il y a quatre données : la moyenne vaut $24:4=6$. Pour $2,3,10$, elle vaut 5, même si aucun résultat ne vaut 5. Si l’on ajoute 1 à chacune des données $4,6,6,8$, la somme augmente de 4 et la moyenne devient $28:4=7$ : elle augmente aussi de 1.'),
bloc('savoirfaire',r'Dans un tableur, placer une donnée par cellule ; \texttt{=MOYENNE(A2:A6)} calcule la moyenne de cinq données. Pour une fréquence, diviser l’effectif par le total puis choisir l’affichage en pourcentage.','Exploiter un tableur'),
bloc('attention',r'Une moyenne seule ne montre pas la dispersion des valeurs. Deux séries peuvent avoir la même moyenne et des profils très différents. La hauteur d’une barre ne se lit qu’après vérification de l’échelle.'))
],[
E('Un effectif total',r'Un relevé comporte 7 réponses A, 9 réponses B et 4 réponses C. Donner l’effectif total.',r'$7+9+4=\res{20}$ réponses. Chaque réponse est comptée une seule fois.','Additionner les catégories.','assert 7+9+4==20'),
E('Une fréquence',r'Sur 25 élèves, 10 choisissent le vélo. Donner la fréquence sous forme de fraction, de décimal et de pourcentage.',r'$10/25=2/5=\res{0{,}4=40\,\%}$. Le total de référence est 25.','Diviser l’effectif de la catégorie par le total.','assert Rational(10,25)==Rational(".4")==Rational(40,100)'),
E('Une moyenne directe',r'Calculer la moyenne de 8, 10, 12 et 14.',r'La somme vaut 44. La moyenne est $44:4=\res{11}$.','Diviser la somme par le nombre de données.','assert Rational(8+10+12+14,4)==11'),
E('Lire des barres',r'Le diagramme donne le nombre de livres lus. Combien d’élèves ont lu deux livres ?',r'La barre d’abscisse 2 atteint l’effectif $\res4$. L’axe horizontal donne les livres et le vertical les élèves.','Lire le rôle de chaque axe.','assert [2,3,4,1][2]==4',figure='stat-4'),
E('Choisir un graphique',r'Pour comparer les effectifs de trois sports et pour montrer une température au fil des heures, choisir deux représentations adaptées.',r'Pour les sports, un $\res{diagramme\ en\ barres}$ permet de comparer les catégories. Pour la température selon l’heure, un $\res{graphique\ cartésien}$ montre l’évolution.','Relier la représentation à l’objectif.','assert len(["sports","temperature"])==2'),
E('Organiser une liste',r'On observe les valeurs $1,2,1,3,2,1,2,2$. Donner les effectifs et fréquences de 1, 2 et 3.',r'Les effectifs sont $3,4,1$, total 8. Les fréquences sont $\res{3/8,\ 1/2,\ 1/8}$, soit 37,5 %, 50 % et 12,5 %. Leur somme vaut 100 %.','Compter puis contrôler le total.','assert [[1,2,1,3,2,1,2,2].count(a) for a in [1,2,3]]==[3,4,1] and Rational(3,8)+Rational(4,8)+Rational(1,8)==1'),
E('Construire des secteurs',r'Sur 20 votes, A en obtient 10, B en obtient 6 et C en obtient 4. Donner les angles du diagramme circulaire puis le construire.',r'Les fréquences sont 50 %, 30 % et 20 %. En multipliant par $360^\circ$, on obtient $\res{180^\circ,\ 108^\circ,\ 72^\circ}$. Le total est 360 degrés.','Traduire les parts du total en parts du tour.','assert [Rational(a,20)*360 for a in [10,6,4]]==[180,108,72]',figure='stat-7'),
E('Lire un secteur',r'Un secteur de diagramme circulaire mesure $90^\circ$ sur un total de 48 personnes. Combien représente-t-il de personnes ?',r'$90/360=1/4$. Un quart de 48 vaut $\res{12}$ personnes.','Rapporter l’angle au tour complet.','assert Rational(90,360)*48==12',figure='stat-8'),
E('Une moyenne décimale',r'Quatre mesures valent 2,4 ; 3,1 ; 2,8 et 3,7 cm. Calculer la moyenne. On ajoute ensuite 0,5 cm à chaque mesure : quelle est la nouvelle moyenne ?',r'La somme vaut 12 cm. La moyenne est $12:4=\res{3\ \mathrm{cm}}$, comprise entre la plus petite et la plus grande mesure. Avec 0,5 cm de plus pour chacune, la somme augmente de $4\times0{,}5=2$ cm : la nouvelle moyenne vaut $14:4=\res{3{,}5\ \mathrm{cm}}$. Elle augmente aussi de 0,5 cm.','Additionner dans la même unité.','m=["2.4","3.1","2.8","3.7"]\nassert sum(map(Rational,m))/4==3 and sum(Rational(a)+Rational("0.5") for a in m)/4==Rational("3.5")'),
E('Une donnée extrême',r'Calculer la moyenne de 4, 5, 6 ; puis celle de 4, 5, 60. Quel effet produit la dernière valeur ?',r'La première moyenne vaut $\res5$. La seconde vaut $69:3=\res{23}$. La valeur 60 tire fortement la moyenne vers le haut.','Comparer les sommes à effectif constant.','assert Rational(4+5+6,3)==5 and Rational(4+5+60,3)==23'),
E('Retrouver une donnée',r'La moyenne de cinq nombres est 12. Quatre de ces nombres sont 8, 11, 13 et 15. Trouver le cinquième.',r'La somme des cinq doit valoir $5\times12=60$. La somme connue vaut 47. Le dernier nombre est $60-47=\res{13}$.','Retrouver d’abord la somme totale.','assert 5*12-(8+11+13+15)==13'),
E('Comparer des groupes',r'Dans A, 12 personnes sur 20 ont réussi ; dans B, 18 sur 40. Quel groupe a le plus grand nombre de réussites ? Le meilleur taux ?',r'B a plus de réussites : 18 contre 12. Mais les taux sont $12/20=60\,\%$ et $18/40=45\,\%$. Le meilleur taux est celui de $\res A$.','Distinguer effectif et fréquence.','assert 18>12 and Rational(12,20)>Rational(18,40)'),
E('Même moyenne, profils différents',r'Comparer les séries $5,5,5,5$ et $0,0,10,10$. Calculer leurs moyennes et expliquer ce que la moyenne ne dit pas.',r'Les deux sommes valent 20, donc les deux moyennes valent $\res5$. La première série est constante, la seconde comporte deux niveaux très éloignés. La moyenne seule masque cette différence.','Revenir aussi aux valeurs individuelles.','assert Rational(5+5+5+5,4)==Rational(0+0+10+10,4)==5'),
E('Une graduation trompeuse',r'Le diagramme compare 48 et 52 personnes avec un axe vertical commençant à 40. Les barres semblent avoir des hauteurs 8 et 12. Le second effectif est-il 1,5 fois le premier ?',r'Non : $12:8=1{,}5$ compare seulement les hauteurs au-dessus de 40. Le rapport réel est $52:48=13/12\approx1{,}083$. La différence est $\res4$ personnes. Il faut lire l’origine tronquée de l’axe.','Contrôler l’échelle avant d’interpréter.','assert Rational(12,8)==Rational("1.5") and Rational(52,48)==Rational(13,12) and 52-48==4',figure='stat-14'),
E('Préparer une enquête',r'On veut connaître le moyen de transport principal de 30 élèves, une réponse par élève. Les réponses donnent 12 à pied, 9 en bus, 6 à vélo et 3 autrement. Donner les fréquences et proposer deux graphiques possibles.',r'Les fréquences sont $\res{40\,\%,30\,\%,20\,\%,10\,\%}$, total 100 %. Un diagramme en barres compare les effectifs ; un circulaire montre les parts, avec angles $144,108,72,36^\circ$. Préciser la question et le groupe interrogé.','Définir la collecte puis choisir la représentation.','assert [Rational(a,30)*100 for a in [12,9,6,3]]==[40,30,20,10] and sum([144,108,72,36])==360',figure='stat-15')
],reperes=['Collecte, effectifs et fréquences','Tableaux, diagrammes et graphiques','Moyenne simple et interprétation','Tableur et lecture critique'],deco='statistiques')
